window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7a7362667b481fe5"]={"versions": [{"id": "FIG-7a7362667b481fe5", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bit- und Byte-Layout-Diagramm (Header-Format) des AUTOSAR E2E Profile 11 Protokolls im Kontext der funktionalen Sicherheit (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Serialisierungs- und Bitbelegungsstruktur der 2 Byte (16 Bit) umfassenden E2E-Header-Felder über der physikalischen Übertragungsreihenfolge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Header-Layout umfasst 2 Bytes (Byte 0 und Byte 1) bzw. 16 Übertragungsbits (Transmission Order 0 bis 15) mit folgenden Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Byte Order 0</strong> (Transmission Order 0–7, Bit Order 7 bis 0): Belegt durch das Feld <code>E2E CRC</code> (8-Bit Prüfsumme).\n</li><li><strong>Byte Order 1</strong> (Transmission Order 8–15): Unterteilt in zwei 4-Bit-Nibbles:\n<ul class=\"fig-list\"><li><code>DataIDNibble</code> auf Transmission Order 8–11 (Bit Order 15, 14, 12, 12).\n</li><li><code>Counter</code> auf Transmission Order 12–15 (Bit Order 11, 10, 9, 8).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die statische Feldzuordnung dar. Zur Laufzeit erfolgt die Übertragung sequentiell von Bit 0 bis Bit 15:</p>\n<ol class=\"fig-list\"><li>Zuerst wird Byte 0 mit der 8-Bit <code>E2E CRC</code> übertragen (Transmission Bits 0 bis 7, entsprechend Bit Order 7 downto 0).\n</li><li>Anschließend wird Byte 1 übertragen (Transmission Bits 8 bis 15), beginnend mit dem höherwertigen Nibble <code>DataIDNibble</code> (Bits 8 bis 11) gefolgt vom niederwertigen Nibble <code>Counter</code> (Bits 12 bis 15).\n</li></ol>\n<p class=\"fig-p\">Auf Empfängerseite erfolgt die Auswertung entsprechend der festgelegten Bit- und Nibble-Positionen zur Verifikation von Zählerkonsistenz und CRC.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des E2E Profile 11 Headers für Sender und Empfänger:</p>\n<ul class=\"fig-list\"><li>Header-Länge: Genau 2 Bytes (16 Bits).\n</li><li>Im dargestellten <code>Bit Order</code>-Schema von Byte 1 ist ein Druckfehler im Dokument enthalten: Für Transmission Order 10 und 11 ist jeweils Bit-Index „12“ angegeben (Folge: 15, 14, 12, 12 anstelle von 15, 14, 13, 12).\n</li><li>Das Feld <code>DataIDNibble</code> belegt 4 Bits und dient der Absicherung gegen Fehlleitung/Verwechslung der Botschafts-ID.\n</li><li>Das Feld <code>Counter</code> belegt 4 Bits (Wertebereich 0–15) zur Erkennung von Paketwiederholungen, Verlust und Reihenfolgefehlern.\n</li><li>Die <code>E2E CRC</code> deckt die zu schützenden Nutzdaten sowie Header-Anteile/DataID gemäß E2E Profile 11 Berechnungsvorschrift ab.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-92fc1aa93bc9f695", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bit- und Byte-Layout-Diagramm (Header-Format) des AUTOSAR E2E Profile 11 Protokolls im Kontext der funktionalen Sicherheit (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Serialisierungs- und Bitbelegungsstruktur der 2 Byte (16 Bit) umfassenden E2E-Header-Felder über der physikalischen Übertragungsreihenfolge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Header-Layout umfasst 2 Bytes (Byte 0 und Byte 1) bzw. 16 Übertragungsbits (Transmission Order 0 bis 15) mit folgenden Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Byte Order 0</strong> (Transmission Order 0–7, Bit Order 7 bis 0): Belegt durch das Feld <code>E2E CRC</code> (8-Bit Prüfsumme).\n</li><li><strong>Byte Order 1</strong> (Transmission Order 8–15): Unterteilt in zwei 4-Bit-Nibbles:\n<ul class=\"fig-list\"><li><code>DataIDNibble</code> auf Transmission Order 8–11 (Bit Order 15, 14, 12, 12).\n</li><li><code>Counter</code> auf Transmission Order 12–15 (Bit Order 11, 10, 9, 8).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die statische Feldzuordnung dar. Zur Laufzeit erfolgt die Übertragung sequentiell von Bit 0 bis Bit 15:</p>\n<ol class=\"fig-list\"><li>Zuerst wird Byte 0 mit der 8-Bit <code>E2E CRC</code> übertragen (Transmission Bits 0 bis 7, entsprechend Bit Order 7 downto 0).\n</li><li>Anschließend wird Byte 1 übertragen (Transmission Bits 8 bis 15), beginnend mit dem höherwertigen Nibble <code>DataIDNibble</code> (Bits 8 bis 11) gefolgt vom niederwertigen Nibble <code>Counter</code> (Bits 12 bis 15).\n</li></ol>\n<p class=\"fig-p\">Auf Empfängerseite erfolgt die Auswertung entsprechend der festgelegten Bit- und Nibble-Positionen zur Verifikation von Zählerkonsistenz und CRC.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des E2E Profile 11 Headers für Sender und Empfänger:</p>\n<ul class=\"fig-list\"><li>Header-Länge: Genau 2 Bytes (16 Bits).\n</li><li>Im dargestellten <code>Bit Order</code>-Schema von Byte 1 ist ein Druckfehler im Dokument enthalten: Für Transmission Order 10 und 11 ist jeweils Bit-Index „12“ angegeben (Folge: 15, 14, 12, 12 anstelle von 15, 14, 13, 12).\n</li><li>Das Feld <code>DataIDNibble</code> belegt 4 Bits und dient der Absicherung gegen Fehlleitung/Verwechslung der Botschafts-ID.\n</li><li>Das Feld <code>Counter</code> belegt 4 Bits (Wertebereich 0–15) zur Erkennung von Paketwiederholungen, Verlust und Reihenfolgefehlern.\n</li><li>Die <code>E2E CRC</code> deckt die zu schützenden Nutzdaten sowie Header-Anteile/DataID gemäß E2E Profile 11 Berechnungsvorschrift ab.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9109f5463b03c7f9", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Bit- und Byte-Layout-Diagramm (Header-Format) des AUTOSAR E2E Profile 11 Protokolls im Kontext der funktionalen Sicherheit (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Serialisierungs- und Bitbelegungsstruktur der 2 Byte (16 Bit) umfassenden E2E-Header-Felder über der physikalischen Übertragungsreihenfolge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Header-Layout umfasst 2 Bytes (Byte 0 und Byte 1) bzw. 16 Übertragungsbits (Transmission Order 0 bis 15) mit folgenden Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Byte Order 0</strong> (Transmission Order 0–7, Bit Order 7 bis 0): Belegt durch das Feld <code>E2E CRC</code> (8-Bit Prüfsumme).\n</li><li><strong>Byte Order 1</strong> (Transmission Order 8–15): Unterteilt in zwei 4-Bit-Nibbles:\n<ul class=\"fig-list\"><li><code>DataIDNibble</code> auf Transmission Order 8–11 (Bit Order 15, 14, 12, 12).\n</li><li><code>Counter</code> auf Transmission Order 12–15 (Bit Order 11, 10, 9, 8).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt die statische Feldzuordnung dar. Zur Laufzeit erfolgt die Übertragung sequentiell von Bit 0 bis Bit 15:</p>\n<ol class=\"fig-list\"><li>Zuerst wird Byte 0 mit der 8-Bit <code>E2E CRC</code> übertragen (Transmission Bits 0 bis 7, entsprechend Bit Order 7 downto 0).\n</li><li>Anschließend wird Byte 1 übertragen (Transmission Bits 8 bis 15), beginnend mit dem höherwertigen Nibble <code>DataIDNibble</code> (Bits 8 bis 11) gefolgt vom niederwertigen Nibble <code>Counter</code> (Bits 12 bis 15).\n</li></ol>\n<p class=\"fig-p\">Auf Empfängerseite erfolgt die Auswertung entsprechend der festgelegten Bit- und Nibble-Positionen zur Verifikation von Zählerkonsistenz und CRC.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des E2E Profile 11 Headers für Sender und Empfänger:</p>\n<ul class=\"fig-list\"><li>Header-Länge: Genau 2 Bytes (16 Bits).\n</li><li>Im dargestellten <code>Bit Order</code>-Schema von Byte 1 ist ein Druckfehler im Dokument enthalten: Für Transmission Order 10 und 11 ist jeweils Bit-Index „12“ angegeben (Folge: 15, 14, 12, 12 anstelle von 15, 14, 13, 12).\n</li><li>Das Feld <code>DataIDNibble</code> belegt 4 Bits und dient der Absicherung gegen Fehlleitung/Verwechslung der Botschafts-ID.\n</li><li>Das Feld <code>Counter</code> belegt 4 Bits (Wertebereich 0–15) zur Erkennung von Paketwiederholungen, Verlust und Reihenfolgefehlern.\n</li><li>Die <code>E2E CRC</code> deckt die zu schützenden Nutzdaten sowie Header-Anteile/DataID gemäß E2E Profile 11 Berechnungsvorschrift ab.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7a7362667b481fe5", "to": "FIG-92fc1aa93bc9f695", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-92fc1aa93bc9f695", "to": "FIG-9109f5463b03c7f9", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
